                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p,qd=a_+dy,b_+dx
                        if 0<=p<H and 0<=qd<W and g[p][qd]==0 and not seen[p][qd]:
                            seen[p][qd]=True; q.append((p,qd))
                out.append(cells)
    return out
for C in comps(gi):
