from collections import deque
def f(g):
    H,W=len(g),len(g[0])
    S={(p,q) for p in range(H) for q in range(W) if g[p][q]==1}
    vis=[[False]*W for _ in range(H)]
    dq=deque()
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and (i in (0,H-1) or j in (0,W-1)) and not vis[i][j]:
                vis[i][j]=True; dq.append((i,j))
    while dq:
        a,b=dq.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            p,qd=a+dy,b+dx
            if 0<=p<H and 0<=qd<W and g[p][qd]==0 and not vis[p][qd]:
                vis[p][qd]=True; dq.append((p,qd))
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0: continue
            nb=any(0<=i+dy<H and 0<=j+dx<W and g[i+dy][j+dx]==1
                   for dy in(-1,0,1) for dx in(-1,0,1) if (dy,dx)!=(0,0))
            if not vis[i][j] and nb:     out[i][j]=2   # enclosed, adjacent to shape -> 3
            elif vis[i][j] and nb:       out[i][j]=2   # outside, adjacent -> 2
            # else stays 0
    return out
